mapper.update:
UPDATE leaf_red_packet
SET status = #{newStatus},
    update_time = #{updateTime}
WHERE id = #{id}
  AND status = 1

UPDATE leaf_red_packet
SET remaining_count = remaining_count - 1,
    remaining_amount = remaining_amount - #{amount},
    version = version + 1,
    update_time = NOW()
WHERE id = #{id}
  AND version = #{version}
  AND remaining_count > 0
  AND remaining_amount >= #{amount}
